class Solution:
    def reversePairs(self, nums: list[int]) -> int:
        self.count = 0
        def merge_sort(arr):
            if len(arr) <= 1:
                return arr
            mid = len(arr) // 2
            left = merge_sort(arr[:mid])
            right = merge_sort(arr[mid:])
            j = 0
            for i in range(len(left)):
                while j < len(right) and left[i] > 2 * right[j]:
                    j += 1
                self.count += j
            return sorted(left + right)
        merge_sort(nums)
        return self.count

